            if index < len(s) and s[index] == ',':
                index += 1
            elif index < len(s) and s[index] == ']':
                return result, index + 1
            else:
                raise ValueError(f"Invalid array syntax at index {index}")

    def parse_object(index: int) -> (dict, int):
