    """
    A simple JSON parser that uses a state machine approach to convert a JSON string into corresponding Python objects.
    Supports parsing for strings, numbers, booleans, null, arrays, and objects.
    """

    index = 0
    length = len(s)

    def parse_value():
        nonlocal index
        if index >= length:
