                index += 1
                return unescape_string(result)
            elif char == '\\':
                index += 1  # skip escape character
            index += 1
        raise ValueError("Unterminated string.")

    def unescape_string(string):
        return bytes(string, "utf-8").decode("unicode_escape")

    def parse_number():
        nonlocal index
