        if s[index] == '-':
            index += 1
        while index < length and (s[index].isdigit() or s[index] == '.'):
            index += 1
        number = s[start:index]
        if '.' in number:
            return float(number)
        return int(number)

    def parse_array():
        nonlocal index
        index += 1  # skip '['
        arr = []
        while index < length:
            char = s[index]
            if char == ']':
                index += 1  # skip ']'
                return arr
            value = parse_value()
            arr.append(value)
            char = s[index]
            if char == ',':
                index += 1  # skip ','
            elif char == ']':
                index += 1  # skip ']'
                return arr
            else:
                raise ValueError(f"Unexpected character in array: {char}")

    def parse_object():
        nonlocal index
        index += 1  # skip '{'
