            value = parse_value()
            obj[key] = value
            char = s[index]
            if char == ',':
                index += 1  # skip ','
            elif char == '}':
                index += 1  # skip '}'
                return obj
            else:
                raise ValueError(f"Unexpected character in object: {char}")

    return parse_value()

